import csv
import datetime as dt
import re
from collections import defaultdict
from decimal import Decimal, ROUND_HALF_UP

DATASET = "/app/dataset"


def _pesel_valid(pesel: str) -> bool:
    if len(pesel) != 11 or not pesel.isdigit():
        return False
    weights = [1, 3, 7, 9, 1, 3, 7, 9, 1, 3]
    checksum = (10 - sum(int(d) * w for d, w in zip(pesel, weights)) % 10) % 10
    return checksum == int(pesel[10])


def _parse_date(s: str):
    try:
        return dt.date.fromisoformat(s.strip())
    except ValueError:
        return None


def _parse_tasks(s: str) -> list[int]:
    # Repairs malformed lists such as "[244, 900, 961" or "146]".
    return [int(x) for x in re.findall(r"\d+", s)]


def _billing_start(d: dt.date, weekday: int) -> dt.date:
    """Start of the billing period containing d: the first `weekday` of a
    month. Days before that in a month belong to the previous period."""
    def first_weekday(year, month):
        first = dt.date(year, month, 1)
        return first + dt.timedelta(days=(weekday - first.weekday()) % 7)

    start = first_weekday(d.year, d.month)
    if d < start:
        prev = d.replace(day=1) - dt.timedelta(days=1)
        start = first_weekday(prev.year, prev.month)
    return start


def answer() -> dict[str, list[int]]:
    with open(f"{DATASET}/employees.csv", newline="", encoding="utf-8") as f:
        employees = {
            r["PESEL"].strip(): float(r["hourly_rate"])
            for r in csv.DictReader(f)
            if _pesel_valid(r["PESEL"].strip())
        }

    with open(f"{DATASET}/tasks.csv", newline="", encoding="utf-8") as f:
        task_pay = {int(r["task_id"]): float(r["pay_per_completion"])
                    for r in csv.DictReader(f)}

    with open(f"{DATASET}/timesheet.csv", newline="", encoding="utf-8") as f:
        rows = list(csv.DictReader(f))

    # The weekday of the dataset's earliest (valid) record defines the payday.
    valid_dates = [d for d in (_parse_date(r["date"]) for r in rows) if d]
    payday_weekday = min(valid_dates).weekday()

    seen = set()
    hours = defaultdict(Decimal)
    bonus = defaultdict(Decimal)
    for r in rows:
        pesel = r["employee_id"].strip()
        # Unknown / checksum-invalid PESELs are ghost records -> excluded.
        if pesel not in employees or not _pesel_valid(pesel):
            continue
        # Non-existent calendar dates (e.g. 2025-04-31) -> excluded.
        d = _parse_date(r["date"])
        if d is None:
            continue
        tasks = _parse_tasks(r["performed_tasks"])
        h = Decimal(r["hours_worked"].strip())
        if h < 0 or h > 24:
            continue
        # Exact duplicates (differing only by row id) -> counted once.
        key = (pesel, d, h, tuple(tasks), r["facility_id"].strip(),
               r["salary_amount"].strip(), r["bonus"].strip())
        if key in seen:
            continue
        seen.add(key)

        period = _billing_start(d, payday_weekday)
        hours[(pesel, period)] += h
        # Bonus recomputed from the task catalogue: unknown task ids and
        # negative / inconsistent bonus values are ignored.
        bonus[(pesel, period)] += sum(
            (Decimal(str(task_pay[t])) for t in tasks if t in task_pay),
            Decimal(0))

    result = defaultdict(list)
    for pesel, period in sorted(hours, key=lambda k: (k[0], k[1])):
        total = (hours[(pesel, period)] * Decimal(str(employees[pesel]))
                 + bonus[(pesel, period)])
        result[pesel].append(
            int(total.quantize(Decimal(1), rounding=ROUND_HALF_UP)))
    return dict(result)


if __name__ == "__main__":
    import json
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)

